════// QuickNav// ═══════════════════════════════════════════════════════════const NAV_KEYS: { id: string; key: string }[] = [  { id: "basic", key: "basic" },  { id: "personal", key: "personal" },  { id: "community", key: "community" },  { id: "professional", key: "professional" },  { id: "family", key: "family" },  { id: "assets", key: "assets" },  { id: "partner-preference", key: "partner_preference" },  { id: "horoscope", key: "horoscope" },  { id: "gallery", key: "gallery" },  { id: "owner", key: "owner" },  { id: "admin", key: "admin" },];const QuickNav: React.FC = () => {  const [activeSection, setActiveSection] = useState("");  const { t } = useLanguage();  useEffect(() => {    const observer = new IntersectionObserver(      (entries) => {        for (const entry of entries) {          if (entry.isIntersecting) {            const id = entry.target.id.replace("section-", "");            setActiveSection(id);          }        }      },      { rootMargin: "-80px 0px -60% 0px", threshold: 0 },    );    NAV_KEYS.forEach((s) => {      const el = document.getElementById(`section-${s.id}`);      if (el) observer.observe(el);    });    return () => observer.disconnect();  }, []);  return (    <div className="no-print relative">      <div className="flex items-center h-11 sm:h-12 overflow-x-auto overflow-y-hidden scrollbar-hide sm:overflow-visible">        {NAV_KEYS.map((s) => {          const isActive = activeSection === s.id;          return (            <button              key={s.id}              onClick={() => {                setActiveSection(s.id);                const el = document.getElementById(`section-${s.id}`);                if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });              }}              className={`h-full px-3 sm:px-5 flex items-center font-serif font-bold                          text-[11px] sm:text-sm whitespace-nowrap shrink-0                          transition-colors duration-200 relative select-none                          ${isActive                            ? "text-rosewood"                            : "text-rosewood/60 hover:text-rosewood"}`}            >              <span>{t(`section_nav.${s.key}`)}</span>              {isActive && (                <div className="absolute bottom-0 left-3 sm:left-5 right-3 sm:right-5 h-0.5 bg-gold rounded-t-full" />              )}            </button>          );        })}      </div>    </div>  );};// ═══════════════════════════════════════════════════════════// AdminProfileHeader (2-col: left info, right photo + status badges)// ═══════════════════════════════════════════════════════════const AdminProfileHeader: React.FC<{  profile: Profile | undefined;  name: string;  location: string;  isTamil: boolean;  getEnumLabel: (value: string, options: any[]) => string;  isLoading: boolean;  onEdit?: () => void;}> = ({ profile, name, location, isTamil, getEnumLabel, isLoading, onEdit }) => {  const { t } = useLanguage();  const { formatDate } = useDateFormatter();  const { calculateAge } = useProfileUtils();  const profilePhoto = profile?.profilePhoto || profile?.photo || (profile?.photos && profile.photos[0]);  const photoUrl: string = (() => {    if (!profilePhoto) return "";    const rawUrl = typeof profilePhoto === 'string' ? profilePhoto : (profilePhoto as any)?.url || "";    return getImageUrl(rawUrl) || "";  })();  if (isLoading) {    return (      <div className="grid grid-cols-1 md:grid-cols-12 gap-6 sm:gap-8">        <div className="md:col-span-8">          <SectionCard3D isLoading>            <SectionHeaderRedesigned title="" isLoading isTamil={isTamil} />            <div className="space-y-0">              {[...Array(6)].map((_, i) => (                <div key={i} className="flex flex-col sm:flex-row py-2 sm:py-1.5 border-b border-gold/10 last:border-0 sm:items-baseline gap-1 sm:gap-0">                  <div className="h-4 w-24 bg-gold/10 rounded animate-pulse sm:w-[160px]" />                  <span className="hidden sm:inline-block w-6 text-center" />                  <div className="h-4 w-3/4 bg-gold/10 rounded animate-pulse" />                </div>              ))}            </div>          </SectionCard3D>        </div>        <div className="md:col-span-4">          <div className="bg-white rounded-xl shadow-sm border border-gold/20 p-4">            <div className="w-full aspect-square rounded-xl bg-gold/10 animate-pulse" />          </div>        </div>      </div>    );  }  if (!profile) return null;  return (    <div className="grid grid-cols-1 md:grid-cols-12 gap-6 sm:gap-8">      <div className="md:col-span-8">        <SectionCard3D>          <SectionHeaderRedesigned            title={t('adminMatrimony.profileView.basicInfo')}            icon={<Info size={16} />}            gradient="bg-rosewood-gradient text-white"            isTamil={isTamil}          >            {onEdit && (              <button onClick={onEdit} className="p-1.5 rounded-lg bg-rosewood-gradient text-white hover:brightness-110 transition-all shadow-sm" title="Edit">                <Pencil size={13} />              </button>            )}          </SectionHeaderRedesigned>          <div className="space-y-0">            <DetailRow label={t('Full Name')} value={name} />            <DetailRow label={t('adminMatrimony.profileView.registrationNo')} value={profile.regNo} />            <DetailRow label={t('Date of Birth')} value={profile.dob ? formatDate(profile.dob) : ''} />            <DetailRow label={t('Age')} value={profile.dob ? `${calculateAge(profile.dob)} ${t('adminMatrimony.profileView.yrs')}` : ''} />            <DetailRow label={t('Gender')} value={profile.gender ? getEnumLabel(profile.gender, GENDER_OPTIONS) : ''} />            <DetailRow label={t('adminMatrimony.profileView.currentLocation')} value={location} />          </div>        </SectionCard3D>      </div>      <div className="md:col-span-4">        <div className="bg-white p-3 sm:p-4 rounded-xl shadow-sm border border-gold/20 flex flex-col items-center">          <div className="w-full max-w-56 sm:max-w-none aspect-square rounded-xl overflow-hidden border-4 border-ivory bg-ivory">            {photoUrl ? (              <img src={photoUrl} alt={name} className="w-full h-full object-cover" loading="lazy" decoding="async" />            ) : (              <div className="w-full h-full bg-ivory flex items-center justify-center">                <span className="text-rosewood/30 text-4xl font-serif font-bold">                  {name?.charAt(0)}                </span>              </div>            )}          </div>        </div>      </div>    </div>  );};// ═══════════════════════════════════════════════════════════// AdminStatusReasons// ═══════════════════════════════════════════════════════════const AdminStatusReasons: React.FC<{ profile: Profile | undefined; isTamil: boolean }> = ({ profile, isTamil }) => {  const { t } = useLanguage();  if (!profile) return null;  const rejectionReason = (profile as any).rejectionReasonEn;  const rejectionReasonTa = (profile as any).rejectionReasonTa;  const blockReason = (profile as any).blockReasonEn;  const blockReasonTa = (profile as any).blockReasonTa;  if (!rejectionReason && !blockReason) return null;  return (    <div className="space-y-3">      {rejectionReason && (        <div className="bg-red-50 rounded-xl p-4 border border-red-100">          <div className="flex items-center gap-2 mb-2">            <span className="text-red-500 font-bold text-xs">!</span>            <p className="text-[9px] text-red-400 font-bold">              {t('adminMatrimony.profileView.rejectionReason')}            </p>          </div>          <p className="text-sm font-bold text-red-800 ml-5">            {isTamil && rejectionReasonTa ? rejectionReasonTa : rejectionReason}          </p>        </div>      )}      {blockReason && (        <div className="bg-amber-50 rounded-xl p-4 border border-amber-100">          <div className="flex items-center gap-2 mb-2">            <span className="text-amber-500 font-bold text-xs">!</span>            <p className="text-[9px] text-amber-400 font-bold">              {t('adminMatrimony.profileView.blockReason')}            </p>          </div>          <p className="text-sm font-bold text-amber-800 ml-5">            {isTamil && blockReasonTa ? blockReasonTa : blockReason}          </p>        </div>      )}    </div>  );};// ═══════════════════════════════════════════════════════════// AdminPersonalDetails// ═══════════════════════════════════════════════════════════const AdminPersonalDetails: React.FC<{  profile: Profile | undefined;  isTamil: boolean;  getEnumLabel: (value: string, options: any[]) => string;  isLoading: boolean;  onEdit?: () => void;}> = ({ profile, isTamil, getEnumLabel, isLoading, onEdit }) => {  const { t } = useLanguage();  return (  <SectionCard3D isLoading={isLoading}>    <SectionHeaderRedesigned      title={t('adminMatrimony.profileView.personalDetails')}      icon={<User size={16} />}      gradient="bg-ivory-gold-gradient text-rosewood"      isLoading={isLoading}      isTamil={isTamil}    >      {onEdit && (        <button onClick={onEdit} className="p-1.5 rounded-lg bg-rosewood-gradient text-white hover:brightness-110 transition-all shadow-sm" title="Edit">          <Pencil size={13} />        </button>      )}    </SectionHeaderRedesigned>    <div className="space-y-0">      <DetailRow label={t('adminMatrimony.profileView.profileFor')} value={profile?.profileFor ? getEnumLabel(profile.profileFor, PROFILE_FOR_OPTIONS) : ''} isLoading={isLoading} />      <DetailRow label={t('Marital Status')} value={profile?.maritalStatus ? getEnumLabel(profile.maritalStatus, MARITAL_STATUS_OPTIONS) : ''} isLoading={isLoading} />      <DetailRow label={t('Diet')} value={profile?.diet ? getEnumLabel(profile.diet, DIET_OPTIONS) : ''} isLoading={isLoading} />      <DetailRow label={t('Height')} value={profile?.height ? getEnumLabel(profile.height.toString(), HEIGHT_OPTIONS) : ''} isLoading={isLoading}